function useCountUp(target, active, duration = 1000, delay = 0) {
  const [value, setValue] = useState(0);
  useEffect(() => {
    if (!active) return;
    let raf;
    let start;
    const timeout = setTimeout(() => {
      const step = (ts) => {
        if (!start) start = ts;
        const progress = Math.min((ts - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        setValue(Math.round(eased * target));
        if (progress < 1) raf = requestAnimationFrame(step);
      };
      raf = requestAnimationFrame(step);
    }, delay);
    return () => {
      clearTimeout(timeout);
      cancelAnimationFrame(raf);
    };
  }, [active, target, duration, delay]);
  return value;
}

function SkillBar({ name, level, delay }) {
  const [ref, visible] = useReveal();
  const count = useCountUp(level, visible, 1100, delay);
  return (
    <div
      ref={ref}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateX(0px)" : "translateX(-14px)",
        transition: `opacity 0.5s ease ${delay}ms, transform 0.5s ease ${delay}ms`,
      }}
    >
      <div className="flex items-center justify-between mb-1.5">
        <span style={{ color: TOKENS.textMid, fontSize: 13.5 }}>{name}</span>
        <span
          style={{
            color: TOKENS.cyan,
            fontSize: 12,
            fontFamily: "'JetBrains Mono', monospace",
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {count}%
        </span>
      </div>
      <div
        className="rounded-full overflow-hidden"
        style={{ height: 6, background: "rgba(255,255,255,0.06)" }}
      >
        <div
          style={{
            height: "100%",
            width: `${level}%`,
            transform: visible ? "scaleX(1)" : "scaleX(0)",
            transformOrigin: "left",
            background: `linear-gradient(90deg, ${TOKENS.violet}, ${TOKENS.cyan})`,
            boxShadow: visible ? `0 0 10px ${TOKENS.cyan}55` : "none",
            transition: `transform 1.1s cubic-bezier(.16,1,.3,1) ${delay}ms, box-shadow 0.6s ease ${delay}ms`,
            borderRadius: 999,
          }}
        />
      </div>
    </div>
  );
}

